CREATE TABLE workspaces (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(160) NOT NULL, demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(160) NOT NULL, email varchar(254) NOT NULL UNIQUE, password_hash varchar(100) NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(40) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permissions (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(80) NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE role_permissions (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role_id bigint NOT NULL REFERENCES roles(id), permission_id bigint NOT NULL REFERENCES permissions(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(role_id,permission_id));
CREATE TABLE workspace_members (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), user_id bigint NOT NULL REFERENCES users(id), role_id bigint NOT NULL REFERENCES roles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,user_id));
CREATE TABLE auth_sessions (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_auth_sessions_expires ON auth_sessions(expires_at);

CREATE TABLE projects (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), name varchar(200) NOT NULL, status varchar(30) NOT NULL CHECK(status IN ('ACTIVE','INACTIVE','COMPLETED','ARCHIVED')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE buildings (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint NOT NULL, name varchar(160) NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id), UNIQUE(project_id,name), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE floors (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint NOT NULL, building_id bigint NOT NULL, number integer NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(building_id,number), FOREIGN KEY(workspace_id,project_id,building_id) REFERENCES buildings(workspace_id,project_id,id));
CREATE TABLE unit_types (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint NOT NULL, name varchar(100) NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(project_id,name), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE units (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint NOT NULL, building_id bigint, unit_number varchar(60) NOT NULL, status varchar(30) NOT NULL CHECK(status IN ('AVAILABLE','RESERVED','SOLD','BLOCKED','UNAVAILABLE')), price numeric(16,2) NOT NULL CHECK(price>=0), area numeric(12,2) NOT NULL CHECK(area>0), bhk integer NOT NULL CHECK(bhk BETWEEN 0 AND 20), property_type varchar(40) NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,project_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,project_id,building_id) REFERENCES buildings(workspace_id,project_id,id));
CREATE UNIQUE INDEX uq_units_number ON units(project_id,coalesce(building_id,0),lower(unit_number));
CREATE INDEX idx_units_recommend ON units(workspace_id,status,price,bhk,area);

CREATE TABLE leads (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), name varchar(160) NOT NULL, phone varchar(30) NOT NULL, email varchar(254), status varchar(30) NOT NULL CHECK(status IN ('NEW','CONTACTED','QUALIFIED','VISIT_PLANNED','VISIT_COMPLETED','HANDED_OVER','NOT_INTERESTED','LOST')), assigned_agent_id bigint, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,assigned_agent_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE UNIQUE INDEX uq_leads_phone ON leads(workspace_id,phone);
CREATE UNIQUE INDEX uq_leads_email ON leads(workspace_id,lower(email)) WHERE email IS NOT NULL AND email<>'';
CREATE TABLE property_documents (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint NOT NULL, title varchar(200) NOT NULL, status varchar(30) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE voice_sessions (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, lead_id bigint NOT NULL, status varchar(40) NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id));
CREATE TABLE appointments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint NOT NULL, lead_id bigint NOT NULL, unit_id bigint, agent_id bigint NOT NULL, scheduled_at timestamptz NOT NULL, duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 15 AND 240), status varchar(30) NOT NULL CHECK(status IN ('REQUESTED','CONFIRMED','RESCHEDULED','CANCELLED','COMPLETED','NO_SHOW')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id), FOREIGN KEY(workspace_id,project_id,unit_id) REFERENCES units(workspace_id,project_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE INDEX idx_appointments_schedule ON appointments(workspace_id,agent_id,scheduled_at);
CREATE INDEX idx_appointments_lead ON appointments(workspace_id,lead_id,scheduled_at);
CREATE TABLE handover_records (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, project_id bigint, lead_id bigint NOT NULL, unit_id bigint, agent_id bigint NOT NULL, appointment_id bigint, status varchar(30) NOT NULL CHECK(status IN ('PENDING','ASSIGNED','ACCEPTED','COMPLETED')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id), FOREIGN KEY(workspace_id,project_id,unit_id) REFERENCES units(workspace_id,project_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES workspace_members(workspace_id,user_id), FOREIGN KEY(workspace_id,appointment_id) REFERENCES appointments(workspace_id,id));
CREATE TABLE lead_recommendations (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL, lead_id bigint NOT NULL, unit_id bigint NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(lead_id,unit_id), FOREIGN KEY(workspace_id,lead_id) REFERENCES leads(workspace_id,id), FOREIGN KEY(workspace_id,unit_id) REFERENCES units(workspace_id,id));
CREATE TABLE notifications (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), user_id bigint, status varchar(40) NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES workspace_members(workspace_id,user_id));
CREATE TABLE audit_logs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), user_id bigint REFERENCES users(id), action varchar(100) NOT NULL, entity_type varchar(80) NOT NULL, entity_id bigint, ip_address varchar(64), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));

-- Support tables are append-only event/snapshot records. Every relationship is tenant scoped.
DO $$
DECLARE item text; parent text; parent_column text; spec text[];
BEGIN
 FOREACH spec SLICE 1 IN ARRAY ARRAY[
 ['project_locations','projects','project_id'],['project_amenities','projects','project_id'],
 ['unit_status_history','units','unit_id'],['unit_prices','units','unit_id'],
 ['lead_contacts','leads','lead_id'],['lead_status_history','leads','lead_id'],['lead_assignments','leads','lead_id'],['lead_preferences','leads','lead_id'],['lead_tags','leads','lead_id'],['lead_notes','leads','lead_id'],['lead_activities','leads','lead_id'],
 ['property_document_versions','property_documents','document_id'],['property_content','property_documents','document_id'],['property_content_versions','property_documents','document_id'],
 ['voice_session_events','voice_sessions','voice_session_id'],['voice_transcripts','voice_sessions','voice_session_id'],['voice_summaries','voice_sessions','voice_session_id'],['voice_session_requirements','voice_sessions','voice_session_id'],
 ['appointment_participants','appointments','appointment_id'],['appointment_status_history','appointments','appointment_id'],['notification_deliveries','notifications','notification_id']
 ] LOOP
  item:=spec[1]; parent:=spec[2]; parent_column:=spec[3];
  EXECUTE format('CREATE TABLE %I (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), project_id bigint, %s data jsonb NOT NULL DEFAULT ''{}'', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id) %s)',item, CASE WHEN parent_column='project_id' THEN '' ELSE format('%I bigint NOT NULL,',parent_column) END, CASE WHEN parent_column='project_id' THEN '' ELSE format(',FOREIGN KEY(workspace_id,%I) REFERENCES %I(workspace_id,id)',parent_column,parent) END);
  EXECUTE format('CREATE INDEX %I ON %I(workspace_id,%I)', 'idx_'||item||'_parent',item,parent_column);
 END LOOP;
 FOREACH item IN ARRAY ARRAY['amenities','lead_sources','files','api_request_logs','outbox_events','idempotency_keys'] LOOP
  EXECUTE format('CREATE TABLE %I (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, workspace_id bigint NOT NULL REFERENCES workspaces(id), project_id bigint, data jsonb NOT NULL DEFAULT ''{}'', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id))',item);
 END LOOP;
 FOREACH item IN ARRAY ARRAY['projects','buildings','floors','unit_types','units','leads','property_documents','voice_sessions','appointments','handover_records','notifications','audit_logs','lead_recommendations','amenities','lead_sources','files','api_request_logs','outbox_events','idempotency_keys'] LOOP
  EXECUTE format('CREATE INDEX %I ON %I(workspace_id,created_at DESC)','idx_'||item||'_workspace',item);
 END LOOP;
END $$;
CREATE INDEX idx_projects_name ON projects(workspace_id,lower(name));
CREATE INDEX idx_leads_name ON leads(workspace_id,lower(name));
CREATE INDEX idx_leads_status ON leads(workspace_id,status);
CREATE INDEX idx_projects_status ON projects(workspace_id,status);
CREATE INDEX idx_units_project ON units(workspace_id,project_id,status);
CREATE INDEX idx_documents_project ON property_documents(workspace_id,project_id,status);
CREATE INDEX idx_audit_entity ON audit_logs(workspace_id,entity_type,entity_id);
